// The small part of JSON that the language server protocol needs, so that the server has no dependency for it.
#pragma once
#include <cstdint>
#include <map>
#include <string>
#include <vector>

namespace blitz::lsp {
	class json {
		public:
		enum class type { null, boolean, number, string, array, object };

		json() = default;
		json(std::nullptr_t) {}
		json(bool v) : _type(type::boolean), _bool(v) {}
		json(int v) : _type(type::number), _number(v) {}
		json(int64_t v) : _type(type::number), _number(double(v)) {}
		json(uint64_t v) : _type(type::number), _number(double(v)) {}
		json(double v) : _type(type::number), _number(v) {}
		json(const char* v) : _type(type::string), _string(v) {}
		json(std::string v) : _type(type::string), _string(std::move(v)) {}

		static json array() { json j; j._type = type::array; return j; }
		static json object() { json j; j._type = type::object; return j; }

		type kind() const { return _type; }
		bool is_null() const { return _type == type::null; }
		bool is_string() const { return _type == type::string; }
		bool is_number() const { return _type == type::number; }
		bool is_object() const { return _type == type::object; }
		bool is_array() const { return _type == type::array; }

		/** The value, or the fallback if this is another kind of value. */
		std::string as_string(std::string const& fallback = std::string()) const { return is_string() ? _string : fallback; }
		int64_t     as_int(int64_t fallback = 0) const { return is_number() ? int64_t(_number) : fallback; }
		bool        as_bool(bool fallback = false) const { return (_type == type::boolean) ? _bool : fallback; }

		/** Member of an object; a null value if there is none (or this is no object). */
		json const& operator[](std::string const& key) const;
		/** Element of an array; a null value if out of range. */
		json const& operator[](size_t index) const;
		bool        has(std::string const& key) const { return is_object() && _object.count(key); }
		size_t      size() const { return is_array() ? _array.size() : (is_object() ? _object.size() : 0); }

		json& set(std::string const& key, json value);
		json& push(json value);
		json& operator[](std::string const& key) { return set_default(key); }

		std::vector<json> const&         items() const { return _array; }
		std::map<std::string, json> const& members() const { return _object; }

		std::string dump() const;

		/** Throws std::runtime_error on malformed text. */
		static json parse(std::string const& text);

		private:
		json& set_default(std::string const& key);
		void  write(std::string& out) const;

		type                        _type   = type::null;
		bool                        _bool   = false;
		double                      _number = 0;
		std::string                 _string;
		std::vector<json>           _array;
		std::map<std::string, json> _object;
	};
} // namespace blitz::lsp
